-- ============================================================
-- Sistema de Gestión de Documentos de una Oficina
-- UNACH · ETDA · Campus IV Tapachula
-- Script de creación de base de datos, tabla y datos de prueba
-- Compatible con MySQL 5.7+ / MariaDB 10.3+ (XAMPP)
-- ============================================================
-- Es seguro ejecutarlo varias veces: no borra nada y los datos de prueba se omiten si ya existen.
-- Los PDF se guardan en la tabla archivos_pdf (la nube no tiene disco persistente).
-- Si usas un MySQL en la nube, omite CREATE DATABASE/USE y ejecuta el resto sobre tu base.

SET NAMES utf8mb4;

CREATE DATABASE IF NOT EXISTS documento
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_spanish_ci;

USE documento;

CREATE DATABASE IF NOT EXISTS documento
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_spanish_ci;

USE documento;

-- ------------------------------------------------------------
-- Tabla principal: documentos recibidos en la oficina
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS documentos (
    id_documento   INT UNSIGNED NOT NULL AUTO_INCREMENT,
    no_oficio      VARCHAR(50)  NOT NULL COMMENT 'Número o folio, ej. 001/2026',
    fecha          DATE         NOT NULL COMMENT 'Fecha de recepción',
    asunto         VARCHAR(255) NOT NULL COMMENT 'Descripción breve',
    remitente      VARCHAR(150) NOT NULL COMMENT 'Persona, dependencia o institución que remite',
    destinatario   VARCHAR(150) NOT NULL COMMENT 'Persona, área o dependencia destinataria',
    estatus        ENUM('Recibido', 'En proceso', 'Atendido') NOT NULL DEFAULT 'Recibido',
    archivo_pdf    VARCHAR(255) NOT NULL COMMENT 'Nombre de referencia del PDF digitalizado',
    creado_en      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (id_documento),
    UNIQUE KEY uq_no_oficio (no_oficio),

    -- Índices para búsquedas y filtros
    KEY idx_fecha        (fecha),
    KEY idx_estatus      (estatus),
    KEY idx_remitente    (remitente),
    KEY idx_destinatario (destinatario)
) ENGINE=InnoDB;

-- ------------------------------------------------------------
-- Contenido binario del PDF (relación 1 a 1 con documentos)
-- MEDIUMBLOB admite hasta 16 MB; la aplicación limita a 4 MB.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS archivos_pdf (
    id_documento INT UNSIGNED NOT NULL,
    contenido    MEDIUMBLOB   NOT NULL,
    PRIMARY KEY (id_documento),
    CONSTRAINT fk_archivo_documento FOREIGN KEY (id_documento)
        REFERENCES documentos (id_documento) ON DELETE CASCADE
) ENGINE=InnoDB;

